import { PieChartComponent } from '@/components/charts/PieChart';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { useEffect, useState } from 'react';
import { format } from 'date-fns';
import { ChartConfig } from '@/components/ui/chart';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import List from '@/features/car/components/statistics/List';
import { AttendanceDashboardChart } from '../../types/attendanceStats.types';

type Props = {
    /** Required by API: GET /attendance-employee-stats?employee_id=… (see NEW_ENDPOINTS.md). */
    employeeId?: string;
};

export default function AttendanceStats({ employeeId }: Props) {
    const [stats, setStats] = useState<AttendanceDashboardChart | null>(null);
    const [loading, setLoading] = useState(true);
    const [selectedValue, setSelectedValue] = useState('');

    useEffect(() => {
        let cancelled = false;
        const fetchStats = async () => {
            setLoading(true);
            if (employeeId) {
                try {
                    const res = await apiGet<{ data: AttendanceDashboardChart }>({
                        endpoint: endpoints.employeeAttendance.analysis,
                        queryParams: {
                            employee_id: employeeId,
                        },
                    });
                    if (!cancelled) setStats(res.data.data);
                } catch {
                    if (!cancelled) setStats(null);
                } finally {
                    if (!cancelled) setLoading(false);
                }
                return;
            }

            try {
                const today = format(new Date(), 'yyyy-MM-dd');
                const first = await apiGet({
                    endpoint: endpoints.employee.attendance,
                    queryParams: { page: 1, pageSize: 1, date: today },
                });
                const total: number = first.data.data.pagination?.total ?? 0;
                if (total === 0) {
                    if (!cancelled) {
                        setStats({ total_days: 0, present: 0, absent: 0, late: 0, leave: 0 });
                    }
                } else {
                    const res = await apiGet({
                        endpoint: endpoints.employee.attendance,
                        queryParams: { page: 1, pageSize: Math.min(total, 5000), date: today },
                    });
                    const rows = res.data.data.data as { attendance_type?: string; status?: string }[];
                    const counts = { present: 0, absent: 0, late: 0, leave: 0 };
                    for (const row of rows) {
                        const s = String(row.attendance_type || row.status || '')
                            .toLowerCase()
                            .trim();
                        if (s === 'present') counts.present++;
                        else if (s === 'absent') counts.absent++;
                        else if (s === 'late') counts.late++;
                        else if (s === 'leave' || s === 'vacation' || s === 'holiday') counts.leave++;
                    }
                    if (!cancelled) setStats({ ...counts, total_days: 0 });
                }
            } catch {
                if (!cancelled) setStats(null);
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        fetchStats();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    let chartData: { days: string; visitors: number; fill: string }[] = [];
    let data: string[] = ['حضور', 'غياب', 'إجازة', 'تأخير'];

    if (stats) {
        const entries: [string, number][] = [
            ['present', stats.present],
            ['absent', stats.absent],
            ['leave', stats.leave],
            ['late', stats.late],
        ];
        chartData = entries.map(([key, value]) => ({
            days: key,
            visitors: value,
            fill: `var(--color-${key})`,
        }));

        data = [
            `${stats.present} حضور`,
            `${stats.absent} غياب`,
            `${stats.leave} إجازة`,
            `${stats.late} تأخير`,
        ];
    }

    const chartConfig = {
        visitors: {
            label: 'Visitors',
        },
        present: {
            label: 'حضور',
            color: 'hsl(var(--chart-1))',
        },
        absent: {
            label: 'غياب',
            color: 'hsl(var(--chart-5))',
        },
        leave: {
            label: 'إجازة',
            color: 'hsl(var(--chart-4))',
        },
        late: {
            label: 'تأخير',
            color: 'hsl(var(--chart-3))',
        },
    } satisfies ChartConfig;

    return (
        <div className="flex flex-col justify-between p-4 shadow-[0px_2px_12px_0px_#14142B14] rounded-[0.5rem]">
            <div className="flex flex-row justify-between mb-4">
                <UnderlineHeading text="الحضور" />
                <CustomSelect
                    options={[
                        { label: 'يومي', value: 'يومي' },
                        { label: 'أسبوعي ', value: 'أسبوعي ' },
                        { label: 'شهري', value: 'شهري' },
                        { label: 'سنوي', value: 'سنوي' },
                    ]}
                    value={selectedValue}
                    onValueChange={setSelectedValue}
                    placeholder="القائمة"
                    width="min-w-[101px]"
                />
            </div>
            <div className="flex flex-row items-center justify-between mb-8">
                {loading ? (
                    <p className="text-sm text-[#625E74] text-end w-full">جاري التحميل…</p>
                ) : !stats ? (
                    <p className="text-sm text-[#625E74] text-end w-full">
                        {employeeId ? 'لا توجد بيانات حضور.' : 'تعذر تحميل بيانات الحضور اليوم.'}
                    </p>
                ) : (
                    <>
                        <List text={data} />
                        <PieChartComponent chartData={chartData} chartConfig={chartConfig} />
                    </>
                )}
            </div>
        </div>
    );
}
